import 'package:flutter/material.dart';import '../controllers/auth_controller.dart';
class LoginPage extends StatefulWidget{final AuthController controller;final VoidCallback onRegister;const LoginPage({super.key,required this.controller,required this.onRegister});@override State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final key=GlobalKey<FormState>();final email=TextEditingController();final password=TextEditingController();@override void dispose(){email.dispose();password.dispose();super.dispose();}Future<void> submit()async{if(!(key.currentState?.validate()??false))return;final ok=await widget.controller.login(email:email.text.trim(),password:password.text);if(!mounted)return;if(!ok)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(widget.controller.errorMessage??'Échec de connexion')));}@override Widget build(BuildContext c)=>Scaffold(body:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Form(key:key,child:Column(children:[const Icon(Icons.local_bar,size:64),const SizedBox(height:16),const Text('LIFETOWN',style:TextStyle(fontSize:28,fontWeight:FontWeight.bold)),const SizedBox(height:24),TextFormField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder()),validator:(v)=>v==null||!v.contains('@')?'Email invalide':null),const SizedBox(height:12),TextFormField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Mot de passe',border:OutlineInputBorder()),validator:(v)=>v==null||v.length<6?'6 caractères minimum':null),const SizedBox(height:20),AnimatedBuilder(animation:widget.controller,builder:(c,_)=>(widget.controller.isLoading?const CircularProgressIndicator():SizedBox(width:double.infinity,child:ElevatedButton(onPressed:submit,child:const Text('Se connecter'))))),TextButton(onPressed:widget.onRegister,child:const Text('Créer un compte'))]))))));}
